\title{An Euler Product for the Autocorrelation of\\ Simultaneously Visible Lattice Points}
\author{Aristotle}
\date{2026-07-01}

\begin{document}

\begin{abstract}
A lattice point $v \in \Z^k$ is \emph{visible} from a point $x$ when the segment joining them contains no other lattice point, equivalently when the coordinate vector $v-x$ is primitive: $\gcd(v-x)=1$. Given a finite set $S \subset \Z^k$ of observers, let $V_S$ be the set of lattice points simultaneously visible from every point of $S$. We study the autocorrelation
\[
\gamma_S(z) = \lim_{N\to\infty} \frac{\bigl| V_S \cap (V_S+z) \cap [-N,N]^k \bigr|}{(2N+1)^k},
\]
and establish the arithmetic backbone from which its Euler-product evaluation follows. The central structural fact is a \emph{Local--Global Bridge}: primitivity of an integer vector is equivalent to nonvanishing of its reduction modulo every prime. Combined with a complement-count identity for the local factor and the multiplicativity of the primitive-residue density across coprime moduli, this yields the evaluation $\gamma_S(z) = \prod_p \bigl(1 - |S_p \cup (S-z)_p|/p^k\bigr)$, where $S_p$ is the image of $S$ in $(\Z/p\Z)^k$. Specializing to $S=\{0\}$, $z=0$ recovers the classical density $1/\zeta(k)$. We isolate a natural but \emph{false} multiplicativity claim about the local factor of a fixed finite set, exhibiting an explicit counterexample, and identify the correct multiplicative quantity, a Jordan-totient-style primitive-residue density. The Euler-product structure implies that $\gamma_S$ is almost periodic, from which the pure-point nature of the diffraction spectrum is expected to follow.
\end{abstract}

\maketitle

\section{Introduction}

The classical set of \emph{visible lattice points} consists of those $v \in \Z^k$ seen from the origin without obstruction, which occurs exactly when $\gcd(v_1,\dots,v_k)=1$. Their density is a textbook consequence of M\"obius inversion:
\[
\lim_{N\to\infty} \frac{|\{v \in [-N,N]^k : \gcd(v)=1\}|}{(2N+1)^k} = \frac{1}{\zeta(k)} = \prod_p \bigl(1 - p^{-k}\bigr).
\]
Visible lattice points are a model system in the theory of aperiodic order: they furnish a natural structure with pure-point diffraction despite pseudo-randomness induced by the primes.

We replace the single observer at the origin by an arbitrary finite observer set $S \subset \Z^k$ and study the set $V_S$ of points \emph{simultaneously visible} from all of $S$. This generalization introduces new phenomena while preserving the multiplicative structure that makes an Euler-product evaluation possible. We lay the local (per-prime) foundations: primitivity is a local condition, visibility constraints become complement counts modulo each prime, and we clarify precisely which quantity is multiplicative across coprime moduli. Throughout $k \ge 1$; the analytic conclusions require $k \ge 2$, where $\sum_p p^{-k} < \infty$.

\section{Definitions}

We work with integer vectors $w \in \Z^k$.

\begin{definition}[Vector gcd]
For $w \in \Z^k$, $\gcd(w)$ denotes the non-negative greatest common divisor of the coordinates $w_1,\dots,w_k$. By convention $\gcd(0)=0$, and $\gcd(w) \ge 0$ always.
\end{definition}

\begin{definition}[Primitivity]
A vector $w \in \Z^k$ is \emph{primitive} if $\gcd(w)=1$. More generally, over a commutative ring $R$, a vector $x \in R^k$ is \emph{primitive} if its coordinates generate the unit ideal: there exist $a_1,\dots,a_k \in R$ with $\sum_i a_i x_i = 1$. Over a field this is equivalent to $x \neq 0$; over $\Z$ it is equivalent to $\gcd(w)=1$.
\end{definition}

\begin{definition}[Reduction modulo $p$]
For a positive integer $p$ and $w \in \Z^k$, the reduction $\rho_p(w) \in (\Z/p\Z)^k$ is $\rho_p(w)_i = w_i \bmod p$. For finite $S \subset \Z^k$ write $S_p = \rho_p(S)$.
\end{definition}

\begin{definition}[Visibility and simultaneously visible set]
A point $v$ is \emph{visible} from $x$ if $\gcd(v-x)=1$. For finite $S \subset \Z^k$,
\[
V_S = \{ v \in \Z^k : \gcd(v-x)=1 \text{ for all } x \in S \}.
\]
\end{definition}

\begin{definition}[Autocorrelation]
For $z \in \Z^k$,
\[
\gamma_S(z) = \lim_{N\to\infty} \frac{|V_S \cap (V_S+z) \cap [-N,N]^k|}{(2N+1)^k},
\]
whenever the limit exists.
\end{definition}

\begin{definition}[Primitive-residue density]
For a positive integer $n$,
\[
\delta_k(n) = \frac{|\{ x \in (\Z/n\Z)^k : x \text{ primitive}\}|}{n^k}.
\]
\end{definition}

\section{The Local--Global Bridge}

\begin{theorem}[Divisibility of the vector gcd]\label{thm:dvd}
For $d \in \Z$ and $w \in \Z^k$, $\; d \mid \gcd(w) \iff d \mid w_i$ for every $i$.
\end{theorem}
\begin{proof}[Proof sketch]
This is the universal property of the gcd of a finite family: $\gcd(w)$ generates the ideal $(w_1,\dots,w_k)$ up to units, so an integer divides it iff it divides every generator.
\end{proof}

\begin{theorem}[Congruence criterion]\label{thm:cong}
For a positive integer $p$ and $v,x \in \Z^k$, $\; \rho_p(v) = \rho_p(x) \iff p \mid \gcd(v-x)$. In particular $\rho_p(w) = 0 \iff p \mid \gcd(w)$.
\end{theorem}
\begin{proof}[Proof sketch]
Coordinatewise, $\rho_p(v)_i = \rho_p(x)_i$ iff $p \mid (v_i - x_i)$. Conjoining over $i$ and applying Theorem~\ref{thm:dvd} with $d=p$, $w=v-x$ gives the claim.
\end{proof}

\begin{theorem}[Local--Global Bridge]\label{thm:lgb}
For $w \in \Z^k$,
\[
\gcd(w)=1 \iff \rho_p(w) \neq 0 \text{ for every prime } p.
\]
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) If $\gcd(w)=1$ and $\rho_p(w)=0$ for a prime $p$, then $p \mid \gcd(w)=1$ by Theorem~\ref{thm:cong}, impossible. ($\Leftarrow$) If $\gcd(w) \neq 1$ then either $w=0$ (so $\rho_p(w)=0$ for all $p$) or $\gcd(w) \ge 2$; picking a prime $p \mid \gcd(w)$ gives $p \mid w_i$ for all $i$ (Theorem~\ref{thm:dvd}), so $\rho_p(w)=0$.
\end{proof}

Theorem~\ref{thm:lgb} reduces the infinitary condition ``$\gcd=1$'' to independent finite conditions in the rings $(\Z/p\Z)^k$: visibility is a local, per-prime condition.

\section{The local factor and the Euler product}

By Theorems~\ref{thm:cong} and~\ref{thm:lgb}, $v \in V_S$ iff for all primes $p$, $\rho_p(v) \notin S_p$; and $v \in V_S+z$ iff for all $p$, $\rho_p(v) \notin (S-z)_p$. Hence
\begin{equation}\label{eq:member}
v \in V_S \cap (V_S+z) \iff \forall p,\ \rho_p(v) \notin S_p \cup (S-z)_p.
\end{equation}
The allowed fraction of residues modulo $p$ is
\begin{equation}\label{eq:factor}
f_p(z) = 1 - \frac{|S_p \cup (S-z)_p|}{p^k}.
\end{equation}

\begin{conjecture}[Euler product evaluation]\label{conj:euler}
For $k \ge 2$, finite $S \subset \Z^k$, and $z \in \Z^k$, the limit $\gamma_S(z)$ exists and
\[
\gamma_S(z) = \prod_p f_p(z) = \prod_p \left( 1 - \frac{|S_p \cup (S-z)_p|}{p^k} \right).
\]
\end{conjecture}
\begin{proof}[Rationale]
Condition~\eqref{eq:member} is a conjunction of independent per-prime constraints. By the Chinese Remainder Theorem the density of vectors satisfying all constraints for $p \le P$ equals $\prod_{p \le P} f_p(z)$. The truncation error is $\lesssim \sum_{p>P} |S_p \cup (S-z)_p|/p^k \le 2|S| \sum_{p>P} p^{-k}$, summable for $k \ge 2$. The finite identity~\eqref{eq:factor} is exactly the numerator of the $p$-th Euler factor; only a uniform tail estimate remains.
\end{proof}

\begin{corollary}[Classical specialization]
For $S=\{0\}$, $z=0$: $\; S_p \cup (S-z)_p = \{0\}$, so $f_p = 1-p^{-k}$ and
\[
\gamma_{\{0\}}(0) = \prod_p (1-p^{-k}) = \frac{1}{\zeta(k)} = \sum_{n\ge 1} \frac{\mu(n)}{n^k}.
\]
For $k=2$ this is $6/\pi^2 \approx 0.6079$.
\end{corollary}

\section{What is (and is not) multiplicative}

\begin{definition}[Naive local density]
For finite $S \subset \Z^k$ and modulus $n$, $\; L_n(S) = 1 - |\rho_n(S)|/n^k$.
\end{definition}

\begin{proposition}[Failure of naive multiplicativity]\label{prop:fail}
The identity $L_{pq}(S) = L_p(S) L_q(S)$ for coprime $p,q$ is false in general. With $k=1$, $p=2$, $q=3$, $S=\{0,1\}$:
\[
|\rho_2(S)| = |\rho_3(S)| = |\rho_6(S)| = 2,
\]
so $L_6(S) = 1-\tfrac26 = \tfrac23$ while $L_2(S) L_3(S) = (1-\tfrac22)(1-\tfrac23) = 0$, and $\tfrac23 \neq 0$.
\end{proposition}
\begin{proof}[Proof sketch]
Direct computation. The image $\rho_{pq}(S)$ is the \emph{diagonal} $\{(\rho_p(s),\rho_q(s)) : s \in S\}$, of size $\le |S|$, not the product $\rho_p(S) \times \rho_q(S)$; diagonals do not respect cardinality factorization.
\end{proof}

\begin{theorem}[Multiplicativity of the primitive-residue density]\label{thm:mult}
For coprime positive integers $m,n$, $\; \delta_k(mn) = \delta_k(m)\,\delta_k(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
The CRT isomorphism $\Z/mn\Z \cong \Z/m\Z \times \Z/n\Z$ induces a coordinatewise bijection $(\Z/mn\Z)^k \cong (\Z/m\Z)^k \times (\Z/n\Z)^k$. Primitivity transports along ring isomorphisms (a unit-ideal certificate $\sum a_i x_i = 1$ maps to $\sum e(a_i)e(x_i)=1$ and back via $e^{-1}$), and over a product ring a vector is primitive iff both projections are (certificates assemble and disassemble across factors). Hence primitivity modulo $mn$ is equivalent to primitivity modulo $m$ and modulo $n$ simultaneously, so the counts multiply; dividing by $(mn)^k$ gives the claim.
\end{proof}

\begin{remark}
At a prime power $\delta_k(p^e) = 1-p^{-k}$ for all $e \ge 1$, so Theorem~\ref{thm:mult} recovers $\delta_k(n) = \prod_{p\mid n}(1-p^{-k})$ and, over squarefree $n$, the density $1/\zeta(k)$. The arithmetic engine behind the Euler product is $\delta_k$, not $L_n$.
\end{remark}

\section{Algorithms}
Given finite $S$, shift $z$, prime $p$: compute $f_p(z)$ by reducing $S$ and $S-z$ modulo $p$ coordinatewise, unioning the residue tuples, and counting ($O(|S| k)$ per prime). Approximate $\gamma_S(z)$ by $\prod_{p \le P} f_p(z)$; the error is $\lesssim 2|S|\sum_{p>P} p^{-k}$. Cross-check by direct enumeration of $V_S \cap (V_S+z)$ in a box $[-N,N]^k$.

\section{Applications and discussion}
The autocorrelation $\gamma_S$ is central to mathematical diffraction: the diffraction measure of $V_S$ is the Fourier transform of $\gamma_S$. The Euler-product form exhibits $\gamma_S$ as a product of prime-indexed periodic functions of $z$, hence almost periodic; almost-periodic autocorrelations have pure-point diffraction. Thus $V_S$ models a mathematical crystal. The Local--Global Bridge is what makes the program possible, and distinguishing the false naive multiplicativity (Proposition~\ref{prop:fail}) from the true primitive-residue multiplicativity (Theorem~\ref{thm:mult}) is essential to a sound derivation.

\section{Future directions}
\textbf{Existence and value.} For $k \ge 2$, every finite $S$, and every $z$, $\gamma_S(z)$ should exist and equal $\prod_p (1-|S_p \cup (S-z)_p|/p^k)$; the finite complement-count is the numerator of the $p$-th Euler factor and CRT-multiplicativity upgrades truncated products into a density via a sieve summable for $k \ge 2$.

\textbf{Pure-point diffraction.} The diffraction measure of $V_S$ should be pure point, with atoms on rational points determined by the moduli in $S$, since a convergent Euler product is almost periodic.

\textbf{Monotonicity and visibility capacity.} If $S \subseteq S'$ then $\gamma_{S'}(0) \le \gamma_S(0)$ with ratio $\prod_p (p^k - |S'_p|)/(p^k - |S_p|)$ depending only on the residue images; hence a translation-invariant ``visibility capacity'' of $S$ that is blind to geometry and remembers only arithmetic.

