"""Euler-product local factor and truncated autocorrelation."""
from math import gcd
from functools import reduce
from typing import Iterable, Sequence, Tuple

Vec = Tuple[int, ...]

def reduce_mod(p: int, w: Sequence[int]) -> Vec:
    return tuple(c % p for c in w)

def primes_up_to(n: int) -> list[int]:
    if n < 2:
        return []
    sieve = bytearray([1]) * (n + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:: i] = bytearray(len(sieve[i * i:: i]))
    return [i for i in range(2, n + 1) if sieve[i]]

def local_factor(S: Iterable[Vec], z: Vec, p: int, k: int) -> float:
    S = list(S)
    residues: set[Vec] = set()
    for s in S:
        residues.add(reduce_mod(p, s))
        residues.add(reduce_mod(p, tuple(si + zi for si, zi in zip(s, z))))
    return 1.0 - len(residues) / (p ** k)

def euler_product(S: Iterable[Vec], z: Vec, k: int, bound: int = 4000) -> float:
    S = list(S)
    prod = 1.0
    for p in primes_up_to(bound):
        prod *= local_factor(S, z, p, k)
    return prod

if __name__ == "__main__":
    print("gamma_{0}(0), k=2 :", euler_product([(0, 0)], (0, 0), 2))
    print("gamma_{0}(1,0), k=2 :", euler_product([(0, 0)], (1, 0), 2))

"""Contrast the FALSE naive local-density multiplicativity with the TRUE
multiplicativity of the primitive-residue density delta_k."""
from math import gcd
from functools import reduce
from itertools import product
from typing import Sequence, Tuple

Vec = Tuple[int, ...]

def vec_gcd(w: Sequence[int]) -> int:
    return reduce(gcd, (abs(c) for c in w), 0)

def reduce_mod(n: int, w: Sequence[int]) -> Vec:
    return tuple(c % n for c in w)

def naive_local_density(S: Sequence[Vec], n: int, k: int) -> float:
    image = {reduce_mod(n, s) for s in S}
    return 1.0 - len(image) / (n ** k)

def primitive_residue_density(n: int, k: int) -> float:
    count = sum(1 for v in product(range(n), repeat=k) if gcd(vec_gcd(v), n) == 1)
    return count / (n ** k)

if __name__ == "__main__":
    S = [(0,), (1,)]
    print("L_6 =", naive_local_density(S, 6, 1),
          " L_2*L_3 =", naive_local_density(S, 2, 1) * naive_local_density(S, 3, 1))
    print("delta_2(6) =", primitive_residue_density(6, 2),
          " delta_2(2)*delta_2(3) =",
          primitive_residue_density(2, 2) * primitive_residue_density(3, 2))

